// ===== CONFIG DA SKILL DE OBRA · o unico lugar pra editar =====
// Preco decidido AQUI, no servidor. O site nunca manda valor.
const CONFIG = {
  PRODUTO_REF: 'skill',                       // external_reference no Mercado Pago
  PRODUTO_ID: 'skill-assistente-obra',        // content_id no pixel/CAPI
  TITULO: 'Skill Assistente de Obra (kit completo)',
  PRECO: 97,                                  // TESTE DE R$ 1: trocar pra 1, testar, VOLTAR PRA 97 antes de lançar
  KIT_URL: 'PREENCHER_LINK_DA_PASTA_DO_KIT',  // link da pasta do kit no Drive (só leitura)
  SITE: 'https://luhpanda.com.br',
  NOTIF_URL: 'https://mcp.luhpanda.com.br/webhook/skill-mp-notificacao',
  EMAIL_LUCIANA: 'lucianapandolfo9@gmail.com',
  PIXEL_ID: '',                               // PREENCHER: ID do conjunto de dados (pixel), só números
  GRAPH_VERSION: 'v26.0',
  CAPI_TEST_CODE: ''                          // opcional: código "TEST..." da aba Eventos de teste
};

let rota = 'desconhecida';
if ($('Webhook criar pagamento').isExecuted) rota = 'criar';
else if ($('Webhook notificação MP').isExecuted) rota = 'notificacao';
else if ($('Webhook acesso').isExecuted) rota = 'acesso';

const kitOk = /^https:\/\/(drive|docs)\.google\.com\//.test(CONFIG.KIT_URL);
const pixelOk = /^\d{6,20}$/.test(CONFIG.PIXEL_ID);

return [{ json: { config: CONFIG, kitOk, pixelOk, rota, entrada: $input.first().json } }];

// Monta a preferência do Mercado Pago. Preço vem do Config, nunca do navegador.
const base = $('Config').first().json;
const config = base.config;
const entrada = base.entrada || {};
const body = entrada.body || {};
const headers = entrada.headers || {};
// O nó Crypto gera hex aleatório; normaliza pra exatamente 32 caracteres.
const token = String($input.first().json.token || '').toLowerCase().replace(/[^a-f0-9]/g, '').slice(0, 32);

if (body.produto !== config.PRODUTO_REF) {
  return [{ json: { ok: false, erro: 'produto_invalido' } }];
}
if (!/^[a-f0-9]{32}$/.test(token)) {
  return [{ json: { ok: false, erro: 'token_invalido' } }];
}

function limpo(v, re, max) {
  const s = String(v || '').trim().slice(0, max);
  return re.test(s) ? s : '';
}
const fbp = limpo(body.fbp, /^fb\.\d\.\d+\.\d+$/, 120);
const fbc = limpo(body.fbc, /^fb\.\d\.\d+\.[A-Za-z0-9_-]+$/, 400);
const pagina = limpo(body.pagina, /^https:\/\/(luhpanda\.com\.br|lucianapandolfo9-spec\.github\.io)\//, 200);
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || '').split(',')[0].trim().slice(0, 64);
const ua = String(headers['user-agent'] || '').slice(0, 400);

const volta = `${config.SITE}/obrigado.html?produto=${config.PRODUTO_REF}&t=${token}`;

const preferencia = {
  items: [{
    id: config.PRODUTO_ID,
    title: config.TITULO,
    description: 'Kit digital: 2 skills para o Claude, planilha modelo de obra e manual em PDF',
    quantity: 1,
    currency_id: 'BRL',
    unit_price: Number(config.PRECO)
  }],
  external_reference: config.PRODUTO_REF,
  back_urls: { success: volta, pending: volta, failure: volta },
  auto_return: 'approved',
  notification_url: config.NOTIF_URL,
  statement_descriptor: 'LUHPANDA',
  metadata: {
    produto: config.PRODUTO_REF,
    token_acesso: token,
    fbp, fbc, ip, ua,
    pagina: pagina || `${config.SITE}/skill-obra.html`
  }
};

return [{ json: { ok: true, preferencia } }];

// Notificação do Mercado Pago: só confia no ID. O resto é buscado na API deles.
// Formatos aceitos: webhook novo (body.data.id / ?data.id=) e IPN antigo (?topic=payment&id=).
const base = $input.first().json;
const e = base.entrada || {};
const q = e.query || {};
const b = e.body || {};

const tipo = String(b.type || q.type || q.topic || b.topic || '');
const id = String((b.data && b.data.id) || q['data.id'] || q.id || '').trim();

if (tipo && tipo !== 'payment') return [];        // merchant_order etc: ignora
if (!/^\d{5,25}$/.test(id)) return [];

return [{ json: { payment_id: id } }];

// Recebe o pagamento lido DIRETO da API do Mercado Pago e decide se é venda nova da skill.
// Monta tudo o que vem depois: linha da planilha, e-mail do comprador, aviso pra Luciana e evento CAPI.
const base = $('Config').first().json;
const config = base.config;
const p = $input.first().json || {};
const md = p.metadata || {};

const ehSkill = p.external_reference === config.PRODUTO_REF && md.produto === config.PRODUTO_REF;
if (!ehSkill || p.status !== 'approved') return [];

const id = String(p.id);

// Trava 1 (rápida): o mesmo pagamento notificado duas vezes não gera dois e-mails.
// A trava 2 (durável) é a consulta na planilha, logo depois deste nó.
const sd = $getWorkflowStaticData('global');
sd.skillPagos = sd.skillPagos || {};
if (sd.skillPagos[id]) return [];
sd.skillPagos[id] = Date.now();
const chaves = Object.keys(sd.skillPagos);
if (chaves.length > 500) chaves.sort((a, b) => sd.skillPagos[a] - sd.skillPagos[b]).slice(0, chaves.length - 500).forEach(k => delete sd.skillPagos[k]);

// ---------- SHA-256 em JS puro (o Code node não tem require('crypto') liberado por padrão) ----------
function sha256(texto) {
  const bytes = [];
  const enc = encodeURIComponent(String(texto));
  for (let i = 0; i < enc.length; i++) {
    if (enc[i] === '%') { bytes.push(parseInt(enc.substr(i + 1, 2), 16)); i += 2; }
    else bytes.push(enc.charCodeAt(i));
  }
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000), lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255, (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < bytes.length; off += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++) w[i] = (bytes[off + i * 4] << 24) | (bytes[off + i * 4 + 1] << 16) | (bytes[off + i * 4 + 2] << 8) | bytes[off + i * 4 + 3];
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

// ---------- dados do comprador ----------
const payer = p.payer || {};
const email = String(payer.email || '').trim().toLowerCase();
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const nome = [payer.first_name, payer.last_name].filter(Boolean).join(' ').trim();
const fone = payer.phone ? String(payer.phone.area_code || '') + String(payer.phone.number || '') : '';
const foneDigitos = fone.replace(/\D/g, '');
const foneE164 = foneDigitos ? (foneDigitos.startsWith('55') ? foneDigitos : '55' + foneDigitos) : '';

const quando = new Date(p.date_approved || p.date_created || Date.now());
const fmt = (opts) => new Intl.DateTimeFormat('pt-BR', Object.assign({ timeZone: 'America/Recife' }, opts)).format(quando);
const valor = Number(p.transaction_amount || 0);
const valorBR = valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const linkAcesso = `${config.SITE}/acesso.html?payment_id=${encodeURIComponent(id)}&t=${encodeURIComponent(md.token_acesso || '')}`;
const primeiroNome = (payer.first_name || '').trim();
const esc = (t) => String(t).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const linha = {
  'Data': fmt({ day: '2-digit', month: '2-digit', year: 'numeric' }),
  'Hora': fmt({ hour: '2-digit', minute: '2-digit' }),
  'Módulo': 'skill',
  'Nome': nome,
  'E-mail': email,
  'Telefone': fone,
  'Valor': valor,
  'Forma': String(p.payment_type_id || p.payment_method_id || ''),
  'ID Pagamento Mercado Pago': id,
  'Status': p.status
};

const emailComprador = {
  para: email,
  assunto: 'Seu kit da Skill Assistente de Obra',
  html: `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#222;max-width:560px">
<p>Oi${primeiroNome ? ' ' + esc(primeiroNome) : ''}!</p>
<p>Seu pagamento de <b>${esc(valorBR)}</b> foi confirmado. Aqui está o seu kit da <b>Skill Assistente de Obra</b>:</p>
<p><a href="${esc(config.KIT_URL)}" style="display:inline-block;background:#FF6B35;color:#2A0E02;text-decoration:none;font-weight:bold;padding:12px 20px;border-radius:8px">Abrir o kit no Google Drive</a></p>
<p><b>Por onde começar:</b></p>
<ol>
<li>Abra o manual de instalação em PDF e siga na ordem.</li>
<li>Faça uma cópia da planilha modelo pro seu Drive.</li>
<li>Suba as 2 skills no Claude e cole o texto das Instruções do Projeto.</li>
</ol>
<p>Lembrete: as skills funcionam no plano pago do Claude, e a foto do comprovante é salva por você no Drive, pelo link que o Claude manda.</p>
<p>Guarde também o link da sua página de acesso: <a href="${esc(linkAcesso)}">${esc(linkAcesso)}</a></p>
<p>Você tem 7 dias de garantia: se não for pra você, é só responder este e-mail que eu devolvo o valor.</p>
<p>Travou na instalação? Me chama pro diagnóstico grátis de 20 minutos no WhatsApp: <a href="https://wa.me/5584994127476">wa.me/5584994127476</a></p>
<p>Luh Panda</p>
</div>`
};

const entregaAuto = emailOk && base.kitOk;
const avisoLuciana = {
  para: config.EMAIL_LUCIANA,
  assunto: `${entregaAuto ? 'Venda' : 'ATENÇÃO: venda sem entrega automática'} · Skill de obra · ${valorBR}`,
  html: `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6">
<p><b>Nova venda da Skill Assistente de Obra</b></p>
<p>Valor: ${esc(valorBR)}<br>Comprador: ${esc(nome || '(sem nome)')}<br>E-mail: ${esc(email || '(sem e-mail)')}<br>Telefone: ${esc(fone || '(sem telefone)')}<br>Forma: ${esc(linha['Forma'])}<br>ID Mercado Pago: ${esc(id)}<br>Data: ${esc(linha['Data'])} ${esc(linha['Hora'])}</p>
<p>Entrega automática por e-mail: <b>${entregaAuto ? 'enviada' : 'NÃO enviada'}</b>${!emailOk ? ' (comprador sem e-mail válido)' : ''}${!base.kitOk ? ' (KIT_URL não preenchido no Config)' : ''}</p>
${entregaAuto ? '' : '<p><b>Entregar o kit na mão.</b></p>'}
<p>Página de acesso do comprador: ${esc(linkAcesso)}</p>
</div>`
};

// ---------- Conversions API (Purchase com valor) ----------
const userData = {};
if (emailOk) userData.em = [sha256(email)];
if (foneE164) userData.ph = [sha256(foneE164)];
if (payer.id) userData.external_id = [sha256('mp_' + String(payer.id))];
if (md.fbp) userData.fbp = String(md.fbp);
if (md.fbc) userData.fbc = String(md.fbc);
if (md.ip) userData.client_ip_address = String(md.ip);
if (md.ua) userData.client_user_agent = String(md.ua);
const fn = String(payer.first_name || '').trim().toLowerCase();
const ln = String(payer.last_name || '').trim().toLowerCase();
if (fn) userData.fn = [sha256(fn)];
if (ln) userData.ln = [sha256(ln)];
userData.country = [sha256('br')];

const evento = {
  event_name: 'Purchase',
  event_time: Math.floor(quando.getTime() / 1000),
  event_id: 'mp_' + id,
  action_source: 'website',
  event_source_url: String(md.pagina || `${config.SITE}/skill-obra.html`),
  user_data: userData,
  custom_data: {
    currency: 'BRL',
    value: valor,
    content_ids: [config.PRODUTO_ID],
    content_type: 'product',
    num_items: 1,
    order_id: id
  }
};
const capi = { data: [evento] };
if (config.CAPI_TEST_CODE) capi.test_event_code = config.CAPI_TEST_CODE;

return [{
  json: {
    payment_id: id,
    linha,
    emailOk,
    entregaAuto,
    emailComprador,
    avisoLuciana,
    capi,
    capiUrl: `https://graph.facebook.com/${config.GRAPH_VERSION}/${config.PIXEL_ID}/events`,
    pixelOk: base.pixelOk
  }
}];

// Pedido da acesso.html: ?payment_id=<id>&t=<token de 32 hex>
const base = $input.first().json;
const q = (base.entrada && base.entrada.query) || {};
const id = String(q.payment_id || '').trim();
const t = String(q.t || '').trim();

if (!/^\d{5,25}$/.test(id) || !/^[a-f0-9]{32}$/.test(t)) {
  return [{ json: { valido: false, resposta: { liberado: false, status: 'link_invalido' } } }];
}
return [{ json: { valido: true, payment_id: id, t } }];

// Decide no SERVIDOR se libera o kit. O pagamento vem direto da API do Mercado Pago.
const base = $('Config').first().json;
const config = base.config;
const pedido = $('Validar pedido de acesso').first().json;
const p = $input.first().json || {};
const md = p.metadata || {};

function resposta(r) { return [{ json: { resposta: r } }]; }

// Comparação em tempo constante do token (evita adivinhar caractere por caractere)
function iguais(a, b) {
  a = String(a || ''); b = String(b || '');
  if (a.length !== b.length || a.length === 0) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}

const ehSkill = String(p.id || '') === pedido.payment_id
  && p.external_reference === config.PRODUTO_REF
  && md.produto === config.PRODUTO_REF
  && iguais(md.token_acesso, pedido.t);

if (!ehSkill) return resposta({ liberado: false, status: 'nao_encontrado' });

if (p.status === 'approved') {
  if (!base.kitOk) return resposta({ liberado: false, status: 'kit_indisponivel' });
  return resposta({ liberado: true, status: 'aprovado', kit_url: config.KIT_URL });
}
if (p.status === 'pending' || p.status === 'in_process' || p.status === 'authorized') {
  return resposta({ liberado: false, status: 'pendente' });
}
return resposta({ liberado: false, status: 'nao_aprovado' });
